 import { Group, Vector3, Color, IcosahedronGeometry, PlaneGeometry, InstancedMesh, InstancedBufferAttribute } from 'three/webgpu';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial, DirectionalLight, AmbientLight } from 'three/webgpu';
import { uv, smoothstep, vec3, mix, uniform, time, sin, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  const timelines = [];

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    background: '#0b0b10',
    surface: '#101017',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [{ at: 0, hex: '#0b0b10' }, { at: 1, hex: '#16161d' }]
  };
  const stops = colors.gradientStops ?? [{ at: 0, hex: '#0b0b10' }, { at: 1, hex: '#16161d' }];
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const cBack = new Color(colors.background);
  const cTop = new Color(stops[stops.length - 1].hex ?? colors.ink);
  const cPaper = new Color(colors.paper);
  const cAccent = new Color(colors.accent);

  // Stage gradient backdrop
  const backdropGeo = new PlaneGeometry(8, 7);
  const backdropMat = new MeshBasicNodeMaterial({ color: cBack });
  backdropMat.colorNode = mix(vec3(uniform(cBack)), vec3(uniform(cTop)), smoothstep(0.0, 1.0, uv().y));
  const backdrop = new ctx.THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // Instanced particle field
  const totalCount = 1200;
  const coreCount = 90;
  const geometry = new IcosahedronGeometry(0.012, 1);
  const paperMat = new MeshStandardNodeMaterial({
    color: cPaper,
    metalness: 0,
    roughness: 1,
    emissive: cPaper,
    emissiveIntensity: 0.9
  });
  const instanceMesh = new InstancedMesh(geometry, paperMat, totalCount);
  instanceMesh.instanceMatrix.setUsage(ctx.THREE.DynamicDrawUsage);
  group.add(instanceMesh);

  const dummy = new ctx.THREE.Object3D();
  const anchors = [];
  const phases = [];
  const coreSet = new Set();
  const ellipsoid = { x: 3, y: 2, z: 2.5 };
  const shellCenter = new Vector3(0, 0, -1.5);
  const origin = new Vector3();

  for (let i = 0; i < totalCount; i++) {
    const anchor = new Vector3(
      (Math.random() - 0.5) * 2 * ellipsoid.x,
      (Math.random() - 0.5) * 2 * ellipsoid.y,
      (Math.random() - 0.5) * 2 * ellipsoid.z + shellCenter.z
    );
    anchors.push(anchor);
    phases.push(new Vector3(Math.random() * Math.PI * 2, Math.random() * Math.PI * 2, Math.random() * Math.PI * 2));
    dummy.position.copy(anchor);
    dummy.scale.setScalar(0.0001);
    dummy.updateMatrix();
    instanceMesh.setMatrixAt(i, dummy.matrix);
  }

  // Pick 90 closest to origin for accent core
  const indexedDist = anchors.map((a, i) => ({ i, d: a.distanceTo(origin) }));
  indexedDist.sort((a, b) => a.d - b.d);
  for (let k = 0; k < coreCount; k++) coreSet.add(indexedDist[k].i);

  // Per-instance colors
  const colorArray = new Float32Array(totalCount * 3);
  for (let i = 0; i < totalCount; i++) {
    const c = coreSet.has(i) ? cAccent : cPaper;
    colorArray[i * 3 + 0] = c.r;
    colorArray[i * 3 + 1] = c.g;
    colorArray[i * 3 + 2] = c.b;
  }
  instanceMesh.instanceColor = new InstancedBufferAttribute(colorArray, 3);

  // Lighting
  group.add(new AmbientLight(cPaper, 0.45));
  const rim = new DirectionalLight(cAccent, 0.75);
  rim.position.set(-4, 3, 5);
  group.add(rim);

  // Text
  const heroItem = textItems.find(t => t.role === 'hero') ?? { text: 'NOVA ATELIER' };
  const subItem = textItems.find(t => t.role === 'subhead') ?? { text: 'Precision instruments for the dark hours.' };
  const capItem = textItems.find(t => t.role === 'caption') ?? { text: 'EST. 2019 / GENEVA AND KYOTO' };

  const heroText = ctx.fontAtlas.createText(heroItem.text, {
    fontSize: 0.62,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: 0
  });
  heroText.position.set(0, 0.5, 0.5);
  group.add(heroText);

  const subText = ctx.fontAtlas.createText(subItem.text, {
    fontSize: 0.2,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: 0
  });
  subText.position.set(0, 0.5 - 0.65, 0.5);
  group.add(subText);

  const capText = ctx.fontAtlas.createText(capItem.text, {
    fontSize: 0.09,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: 1
  });
  capText.position.set(0, -2.25, 0.5);
  group.add(capText);

  // Depth falloff: compute per-instance opacity in update loop (no raw material override since TSL instancing alpha is complex; instead fade scale/alpha visually not shown ... we rely on fog for depth)
  // Fog shader via colorNode on particles? InstancedMesh uses one material; we let the fog/depth read via scene fog, but add custom local opacity per distance by rebuilding nothing. We simulate via scale fade by z.
  // Better: use material properties can't be per instance with NodeMaterial unless custom attributes. We'll emulate by scaling near-zero for far points in update.

  // Animation state
  const emerge = { p: 0 };
  const emergeTimeline = gsap.timeline({ paused: true });
  emergeTimeline.to(emerge, {
    p: 1,
    duration: 1.4,
    ease: 'power3.out'
  });
  timelines.push(emergeTimeline);
  emergeTimeline.play();

  const clock = new ctx.THREE.Clock();
  const updateLoop = () => {
    const now = clock.getElapsedTime();
    const progress = emerge.p;
    const maxDist = Math.max(...anchors.map(a => a.distanceTo(origin)), 0.001);

    for (let i = 0; i < totalCount; i++) {
      const anchor = anchors[i];
      const phase = phases[i];
      const drift = new Vector3(
        Math.sin(now * 0.314 + phase.x) * 0.04,
        Math.cos(now * 0.314 + phase.y) * 0.04,
        Math.sin(now * 0.314 + phase.z) * 0.04
      );
      const target = anchor.clone().add(drift);
      const start = origin.clone();
      const emergent = start.lerp(target, progress);
      dummy.position.copy(emergent);
      // stagger by distance during emergence
      const stagger = 1 - Math.min(1, anchor.distanceTo(origin) / maxDist);
      const localProgress = Math.min(1, progress * (1.4 + stagger));
      const farFade = smoothstep(-5, 0, anchor.z) * 0.75 + 0.25; // not used; rely on fog
      dummy.scale.setScalar(Math.max(0.0001, localProgress));
      dummy.updateMatrix();
      instanceMesh.setMatrixAt(i, dummy.matrix);
    }
    instanceMesh.instanceMatrix.needsUpdate = true;

    // Core pulse on emissive intensity
    const pulse = 1.5 + Math.sin(now * 0.62831) * 0.3; // 0.1 Hz between 1.5 and 1.8
    paperMat.emissiveIntensity = 0.9 + pulse * 0.2;
  };
  const rafId = { value: null };
  const loop = () => {
    updateLoop();
    rafId.value = requestAnimationFrame(loop);
  };
  rafId.value = requestAnimationFrame(loop);

  // Apply cinematic primitives
  const primitives = config.cinematicPrimitives ?? config.intent?.visualSpec?.cinematicPrimitives ?? [];
  const primitiveCleanups = [];
  for (const prim of primitives) {
    if (ctx.primitives[prim.name]) {
      const result = ctx.primitives[prim.name](group, prim.params);
      if (result?.timeline) timelines.push(result.timeline);
      if (result?.cleanup) primitiveCleanups.push(result.cleanup);
      if (prim.trigger === 'load' && result?.timeline?.play) result.timeline.play();
    }
  }

  group.userData.handlers = {};
  group.userData.cleanup = () => {
    cancelAnimationFrame(rafId.value);
    timelines.forEach(tl => tl?.kill());
    primitiveCleanups.forEach(fn => { try { fn(); } catch {} });
    geometry.dispose();
    backdropGeo.dispose();
    backdropMat.dispose();
    paperMat.dispose();
    if (instanceMesh.parent) instanceMesh.parent.remove(instanceMesh);
  };

  return group;
}
